'use client';
import { useEffect, useId, useMemo, useRef, useState, type CSSProperties, type KeyboardEvent, type ReactNode } from 'react';
import { spring as SPRING, springToLinear, useStudioMotion, type SpringToken } from '../../motion';
import type { EffectProps } from '../../types';
import styles from './styles.module.css';

type Params = { depth: number; travel: number; spring: string; tone: string; loadTime: number };
type Tone = 'signal' | 'ink' | 'paper';

const isToken = (v: string): v is SpringToken => v in SPRING;
const isActivationKey = (k: string) => k === ' ' || k === 'Enter';

interface KeyProps {
  tone: Tone;
  wide?: boolean;
  locked?: boolean;
  busy?: boolean;
  describedBy?: string;
  onActivate: () => void;
  children: ReactNode;
  busyLabel?: string;
}

/** One keycap. The pressed look is local state; busy/locked come from the panel. */
function Key({ tone, wide, locked = false, busy = false, describedBy, onActivate, children, busyLabel }: KeyProps) {
  const [pressed, setPressed] = useState(false);
  const inert = locked || busy;
  const down = () => { if (!inert) setPressed(true); };
  const up = () => setPressed(false);
  const onKeyDown = (e: KeyboardEvent<HTMLButtonElement>) => {
    if (!isActivationKey(e.key)) return;
    // Holding Enter auto-repeats clicks on a native button: one press, one activation.
    if (e.repeat) { e.preventDefault(); return; }
    down();
  };
  return (
    <button
      type="button"
      className={styles.key}
      data-tone={tone}
      data-wide={wide || undefined}
      data-pressed={pressed || undefined}
      data-busy={busy || undefined}
      data-locked={locked || undefined}
      aria-disabled={inert || undefined}
      aria-describedby={describedBy}
      onPointerDown={(e) => { if (e.button === 0) down(); }}
      onPointerUp={up}
      onPointerLeave={up}
      onPointerCancel={up}
      onKeyDown={onKeyDown}
      onKeyUp={(e) => { if (isActivationKey(e.key)) up(); }}
      onBlur={up}
      onClick={() => { if (!inert) onActivate(); }}
    >
      <span className={styles.shadow} aria-hidden="true" />
      <span className={styles.side} aria-hidden="true" />
      <span className={styles.face}>
        <span className={styles.labels}>
          <span data-shown={!busy || undefined}>{children}</span>
          {busyLabel ? <span data-shown={busy || undefined}>{busyLabel}</span> : null}
        </span>
        {busyLabel ? <span className={styles.bar} aria-hidden="true" /> : null}
      </span>
    </button>
  );
}

export default function PressDepthButton({ params }: EffectProps<Params>) {
  const { reduced } = useStudioMotion();
  const uid = useId();
  const tone: Tone = params.tone === 'ink' || params.tone === 'paper' ? params.tone : 'signal';
  const release = useMemo(() => springToLinear(SPRING[isToken(params.spring) ? params.spring : 'pop']), [params.spring]);

  const [printing, setPrinting] = useState<null | 'print' | 'reprint'>(null);
  const [printed, setPrinted] = useState(0);
  const [display, setDisplay] = useState('Ready');
  const timer = useRef<number | undefined>(undefined);
  useEffect(() => () => window.clearTimeout(timer.current), []);

  const run = (kind: 'print' | 'reprint') => {
    if (printing) return;
    const n = kind === 'print' ? printed + 1 : printed;
    const no = String(n).padStart(2, '0');
    setPrinting(kind);
    setDisplay(kind === 'print' ? `Printing badge ${no}…` : `Reprinting badge ${no}…`);
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => {
      setPrinting(null);
      if (kind === 'print') setPrinted(n);
      setDisplay(`Badge ${no} ${kind === 'print' ? 'printed' : 'reprinted'} (demo)`);
    }, params.loadTime);
  };

  const style = {
    '--depth': params.depth,
    '--travel': params.travel / 100,
    '--release-ease': release.easing,
    '--release-dur': `${release.duration}ms`,
    '--load': `${params.loadTime}ms`,
  } as CSSProperties;

  return (
    <div className={styles.root} data-reduced={reduced || undefined} style={style}>
      <section className={styles.panel} aria-labelledby={`${uid}title`}>
        <header className={styles.head}>
          <h3 id={`${uid}title`} className={styles.title}>Badge printer</h3>
          <span className={styles.model}>Fictional device · BP-02</span>
        </header>

        <div className={styles.display}>
          <p className={styles.readout} role="status">{display}</p>
          <p className={styles.count}><span>{String(printed).padStart(2, '0')}</span> printed</p>
        </div>

        <div className={styles.keys}>
          <Key tone={tone} wide busy={printing === 'print'} busyLabel="Printing…" onActivate={() => run('print')}>Print badge</Key>
          <Key tone="paper" onActivate={() => setDisplay(`Preview: badge ${String(printed + 1).padStart(2, '0')} (demo)`)}>Preview</Key>
          <Key tone="paper" locked={printed === 0} busy={printing === 'reprint'} busyLabel="Printing…" describedBy={`${uid}reprint`} onActivate={() => run('reprint')}>Reprint</Key>
        </div>

        <p id={`${uid}reprint`} className={styles.note}>
          {printed === 0 ? 'Reprint unlocks after the first badge is printed.' : 'Reprint repeats the last badge.'}
        </p>
      </section>
    </div>
  );
}

.root {
  box-sizing: border-box;
  container-type: inline-size;
  width: min(100% - 2rem, 34rem);
  margin: clamp(1.5rem, 5cqi, 3rem) auto;
  color: var(--mk-ink, #11110f);
  font-family: var(--mk-font-text, ui-sans-serif, system-ui, sans-serif);
}

/* ── Panel ────────────────────────────────────────────────────────────── */
.panel {
  isolation: isolate;
  display: grid;
  gap: clamp(1rem, 3.5cqi, 1.5rem);
  padding: clamp(1rem, 4.5cqi, 1.75rem);
  border: 1px solid var(--mk-line, #11110f24);
  border-radius: var(--mk-radius-l, 18px);
  background: color-mix(in oklab, var(--mk-surface-2, #e9e5da) 55%, var(--mk-surface, #fbf9f4));
}
.head {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.25rem 1rem;
}
.title {
  margin: 0;
  font-family: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif);
  font-size: clamp(1.375rem, 5cqi, 1.75rem);
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.03em;
}
.model, .note {
  font-family: var(--mk-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  letter-spacing: 0.06em;
  color: var(--mk-ink-muted, #5c5a52);
}
.model { text-transform: uppercase; letter-spacing: 0.08em; }
.note { margin: 0; letter-spacing: 0.02em; font-size: 0.75rem; line-height: 1.5; }

.display {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.25rem 1rem;
  padding: 0.875rem 1rem;
  border-radius: var(--mk-radius-m, 10px);
  background: var(--mk-ink, #11110f);
  color: var(--mk-surface, #fbf9f4);
  font-family: var(--mk-font-mono, ui-monospace, monospace);
  font-size: 0.8125rem;
  line-height: 1.4;
  font-variant-numeric: tabular-nums;
  box-shadow: inset 0 1px 3px rgb(0 0 0 / 0.28);
}
.readout { margin: 0; min-height: 1.4em; }
.count { margin: 0; font-size: 0.75rem; letter-spacing: 0.06em; text-transform: uppercase; }
.count span { font-size: 0.8125rem; }

.keys {
  display: grid;
  grid-template-columns: minmax(0, 1.7fr) minmax(0, 1fr) minmax(0, 1fr);
  gap: 1rem 0.75rem;
  padding-block: 0.25rem 0.125rem;
}
@container (max-width: 27rem) {
  .keys { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); }
  .key[data-wide] { grid-column: 1 / -1; }
}

/* ── Keycap ───────────────────────────────────────────────────────────── */
.key {
  --d: calc(var(--depth, 8) * 1px);
  --face: var(--mk-surface-2, #e9e5da);
  --text: var(--mk-ink, #11110f);
  --side: color-mix(in oklab, var(--mk-surface-2, #e9e5da) 62%, #000);
  --line: var(--mk-line, #11110f24);
  --lip: rgb(255 255 255 / 0.5);
  position: relative;
  display: grid;
  min-width: 2.75rem;
  margin: 0;
  padding: 0 0 var(--d);
  border: 0;
  border-radius: 14px;
  background: none;
  color: var(--text);
  font: inherit;
  cursor: pointer;
  user-select: none;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}
.key[data-tone='signal'] {
  --face: var(--mk-signal, #bf2f09);
  --text: var(--mk-on-signal, #ffffff);
  --side: color-mix(in oklab, var(--mk-signal, #bf2f09) 58%, #000);
  --line: transparent;
  --lip: rgb(255 255 255 / 0.24);
}
.key[data-tone='ink'] {
  --face: var(--mk-ink, #11110f);
  --text: var(--mk-surface, #fbf9f4);
  --side: color-mix(in oklab, var(--mk-ink, #11110f) 74%, var(--mk-surface, #fbf9f4));
  --line: transparent;
  --lip: rgb(255 255 255 / 0.16);
}
.key:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 3px; }

.shadow {
  position: absolute;
  z-index: -1;
  inset: auto 9% calc(var(--d) * -0.55) 9%;
  height: 55%;
  border-radius: 50%;
  background: rgb(0 0 0 / 0.24);
  filter: blur(8px);
  transform-origin: 50% 100%;
  transition:
    transform var(--release-dur, 600ms) var(--release-ease, ease),
    opacity var(--release-dur, 600ms) var(--release-ease, ease);
}
.side {
  position: absolute;
  inset: var(--d) 0 0;
  border-radius: inherit;
  background: var(--side);
  box-shadow: inset 0 0 0 1px var(--line);
}
.face {
  position: relative;
  display: grid;
  place-items: center;
  min-height: 3.5rem;
  padding: 0 1.375rem;
  border-radius: inherit;
  background: var(--face);
  box-shadow: inset 0 0 0 1px var(--line), inset 0 1px 0 var(--lip);
  font-size: 1rem;
  font-weight: 600;
  letter-spacing: -0.01em;
  white-space: nowrap;
  transform: translateY(0);
  transition: transform var(--release-dur, 600ms) var(--release-ease, ease);
}

/* Pressed: fast, decelerating travel down; the shadow collapses under the key. */
.key[data-pressed] .face {
  transform: translateY(calc(var(--d) * var(--travel, 0.85)));
  transition: transform var(--mk-duration-instant, 90ms) var(--mk-ease-standard, ease);
}
.key[data-pressed] .shadow {
  transform: translateY(calc(var(--d) * -0.55)) scale(0.9, 0.5);
  opacity: 0.55;
  transition:
    transform var(--mk-duration-instant, 90ms) var(--mk-ease-standard, ease),
    opacity var(--mk-duration-instant, 90ms) var(--mk-ease-standard, ease);
}

/* Busy: the key stays half down while the job runs. */
.key[data-busy] { cursor: progress; }
.key[data-busy] .face { transform: translateY(calc(var(--d) * var(--travel, 0.85) * 0.5)); }
.key[data-busy] .shadow { transform: translateY(calc(var(--d) * -0.3)) scale(0.95, 0.75); opacity: 0.75; }

/* Locked: sunk flush with its base, flat and quiet; it springs up when it unlocks. */
.key[data-locked] { cursor: not-allowed; }
.key[data-locked] .face {
  transform: translateY(var(--d));
  background: color-mix(in oklab, var(--mk-surface-2, #e9e5da) 70%, var(--mk-surface, #fbf9f4));
  color: var(--mk-ink-muted, #5c5a52);
  box-shadow: inset 0 0 0 1px var(--mk-line, #11110f24);
}
.key[data-locked] .shadow { transform: translateY(calc(var(--d) * -0.7)) scale(0.85, 0.3); opacity: 0; }

.labels { display: grid; }
.labels > span { grid-area: 1 / 1; text-align: center; visibility: hidden; }
.labels > span[data-shown] { visibility: visible; }

.bar {
  position: absolute;
  inset: auto 1.125rem 0.5rem;
  height: 2px;
  border-radius: 1px;
  background: currentColor;
  transform: scaleX(0);
  transform-origin: 0 50%;
  opacity: 0;
}
.key[data-busy] .bar {
  opacity: 1;
  transform: scaleX(1);
  transition: transform var(--load, 1800ms) var(--mk-ease-inOut, ease-in-out);
}

/* Reduced motion: every state is applied instantly; the display text carries progress. */
.root[data-reduced] .face,
.root[data-reduced] .shadow,
.root[data-reduced] .key[data-pressed] .face,
.root[data-reduced] .key[data-pressed] .shadow { transition: none; }
.root[data-reduced] .bar { display: none; }
